def is_even(n):
    return n % 2 == 0

def grade(marks):
    if marks >= 90:
        return "A"
    if marks >= 75:
        return "B"
    if marks >= 40:
        return "C"
    return "F"

print(is_even(10), is_even(7))
for m in [95, 80, 52, 12]:
    print(m, grade(m))

